Item.method_code:
/*
  やるやら変更承認のキャンセル時の処理
  - やるやらはそのまま（変更される場合は承認時に変更する）
  - やるやら理由を空欄にする
*/

using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
{
  Innovator inn = getInnovator();
  
  // WFアイテムから対象アイテム取得
  Item reqDocItem = inn.newItem("Method", "h4_GetControlledItem");
  reqDocItem.setID(this.getID());
  reqDocItem = reqDocItem.apply();
  if (reqDocItem.isError())
  {
      return inn.newError(reqDocItem.getErrorString());
  }
  
  //WFの対象が必要資料以外の場合実行しない
  if(reqDocItem.getType() != "h4_ReqDoc")
  {
      return this;
  }

  var workItem = inn.newItem("h4_ReqDoc","edit");
  workItem.setID(reqDocItem.getID());
  workItem.setProperty("h4_yryr_reason","");
  workItem.setAttribute("version","0");
  workItem.setAttribute("serverEvents","0");
  workItem = workItem.apply();
  if(workItem.isError())
  {
    return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
  }
}
return this;
